#pragma once

// The data sets of the FL engines LYNX reproduces (round 190rh: the natives work without FL Studio installed).
//
// Some engines read tables, cycles or samples of the user's own FL installation at run time; the file's path is the
// channel's ChannelDef::samplePath. Without FL there was nothing to read and the engine could not be used. LYNX now has a
// data set of its OWN for them: generated by the code of NativeDataSets.cpp from textbook formulas, circuit models and
// noise generators — no table, recording or preset of FL Studio is stored, converted or fitted point by point.
//
// Which set a channel plays is in its samplePath, so a project says it by itself and its sound never changes silently:
//   - a path of FL's file             FL's data (bit-identical to before). When the file is not there, the same file of
//                                     this computer's FL installation (another drive, a Wine prefix, a newer FL); when
//                                     there is none, or its build is not one LYNX can read, LYNX's own set plays — the
//                                     path stays in the project as it is, and the channel window says so
//   - "lynxdata:<engine>/<revision>"  LYNX's own set, also on a computer with FL. The revision freezes the sound: a better
//                                     set gets the next number, old projects keep theirs
// Nothing rewrites the choice on load or save; "Use FL Studio's data" / "Use LYNX's data" in the channel window do.

#include <cstdint>
#include <functional>
#include <string>
#include <vector>

#include "core/Song.h"

namespace lynx::nativedata
{
constexpr const char* scheme = "lynxdata:";

// true for a reserved path (any engine, any revision): never a file — not missing, packed, collected or relinked
bool isOwn (const std::string& path) noexcept;

// the path of an engine's own set in its newest revision; "" = the engine has none (or needs no data)
std::string ownPath (InstrumentKind kind);
bool hasOwnSet (InstrumentKind kind);
// the revision of `path` for that engine (1…), 0 when it is not its path (a later LYNX's revision counts as the newest
// this one knows, so a newer project still plays)
int ownRevision (const std::string& path, InstrumentKind kind) noexcept;

// This computer's FL installation (FlPathRoots::factoryData; "" = none). The app sets it once at start; the core's tests
// set what they need. Thread-safe.
void setFactoryData (const std::string& folder);
std::string factoryData();

// true for a path that names a file of FL's plugins ("...\\Plugins\\Fruity\\..."), wherever FL is
bool isFlFile (const std::string& path);

// The file (or folder) to read for a channel's path: itself when it exists, else the same file of this computer's FL
// installation (matched from "Plugins\Fruity\" on), else the path unchanged. Reserved paths come back unchanged.
std::string locate (const std::string& path);

// ---- LYNX's own sets -----------------------------------------------------------------------------------------------
// All deterministic: the same on every computer (apart from the last bits of the platform's sin / exp).

// Transistor Bass' "303 Pulse": `count` single cycles at `rate`, longest first, one per semitone from 16.35 Hz up: the
// engine's saw through a saturating transistor stage (Open303's published shape) and a 10 Hz coupling, zero mean.
std::vector<std::vector<float>> bassPulseCycles (double rate, int count);

// MiniSynth's oscillator: 1024 cosine amplitudes and phases, the Fourier series of a falling saw
void fallingSaw (std::vector<float>& amplitude, std::vector<float>& phase);

// Sawer's oscillator: one cycle of 8192 points of a band-limited falling saw
std::vector<float> sawCycle();

// BassDrum: one cycle of a sine (1024 points, at the plugin's rendered level), and noise samples at 44.1 kHz for its noise section. The names LYNX's own
// presets use are "LYNX Hiss", "LYNX Crush", "LYNX Metal" and "LYNX Clap"; any other name (a state made with FL's samples)
// gets the one its words suggest, else the hiss.
std::vector<float> sineCycle (int points);
std::vector<float> drumNoise (const std::string& name);

// Morphine: the noise layer of that name, at 44.1 kHz (a word that says a hit or a click: drumNoise; "brown" or "low": brown
// noise; else steady white noise, two seconds that loop)
std::vector<float> noiseLayer (const std::string& name);

// Kepler: a triangle LFO (one cycle, −1…1, rising from 0) and white noise as 16-bit samples
std::vector<float> triangleCycle (int points);
std::vector<std::int16_t> whiteNoise16 (int points);

// Toxic Biohazard's built-in waves 2…32: amplitude of harmonic h (1…128) of LYNX's own wave `wave`
float toxicHarmonic (int wave, int harmonic);

// DrumSynth Live's wave `wave` (0…17) as `points` samples at 22.05 kHz: metal, cowbell, hats, cymbals, noises, clicks
std::vector<float> drumSynthWave (int wave, int points);

// BooBass: the six zones of its multisample, an electric bass string computed as a plucked string's partials (the pluck's
// comb, a high partial decaying faster): `attack` at 16 kHz ending on a whole cycle, `loop` one cycle of 2048 points that
// carries on from it, `semitone` the zone's root above C0
struct BassZone
{
    int semitone = 0;
    std::vector<float> attack, loop;
};
std::vector<BassZone> bassString();

// FL Slayer: a pick's push on a string, 29 of them by index (noise bursts of different length, colour and hardness), as
// 16-bit samples; the twelve chords of the chord modes as semitones above the engine's lowest note (six strings, −1
// ends a chord): the open position's root–fifth–octave–third shape moved along the neck; and the note lengths of the two glide modes
std::vector<std::int16_t> guitarPick (int index);
std::vector<int> guitarChord (int root);
std::vector<float> glideLengths (bool dynamic);

// The name of one of LYNX's own noises ("LYNX Hiss"; a file of the user's would have an extension)
bool isOwnNoise (const std::string& name);

// GMS: one cycle (1024 points) of the wave of that name (core/NativeWavesGms.cpp); an unknown name is a saw
std::vector<float> gmsWave (const std::string& name);

// the level of each set: 1 = the textbook shape's own; placed so that rendered audio is as loud as the plugin's
constexpr double bassPulseLevel = 0.88, miniSynthLevel = 0.865, sawerLevel = 0.507, bassDrumLevel = 0.856, gmsLevel = 1.0, keplerNoiseLevel = 1.32, bassStringLevel = 1.17;
} // namespace lynx::nativedata
